ok = 0
for did, title, u in urls:
    try:
        r = requests.head(u, timeout=5)
        if r.status_code == 200:
            ok += 1
        else:
            broken.append((did, title, u, r.status_code))
    except Exception as e:
        broken.append((did, title, u, str(e)))

